def slow_start(cwnd, ssthresh, acked, lost):
    # TCP 拥塞控制：慢启动（cwnd 每 RTT 翻倍）→ 阈值后拥塞避免（线性+1）
    # cwnd=拥塞窗口 ssthresh=慢启动阈值 acked=本 RTT 确认数 lost=是否丢包
    if lost:
        ssthresh = max(cwnd // 2, 1)
        cwnd = 1
        return {'cwnd': cwnd, 'ssthresh': ssthresh}
    if cwnd < ssthresh:
        return {'cwnd': min(cwnd + acked, ssthresh), 'ssthresh': ssthresh}
    return {'cwnd': cwnd + 1, 'ssthresh': ssthresh}

