def iter_protocol(data):
    # 迭代器协议：__iter__/__next__（next 逐个取值，耗尽抛 StopIteration）
    it = iter(data)
    out = []
    while True:
        try:
            out.append(next(it))
        except StopIteration:
            break
    return out

